update public.theme_maps set description = '전국 곳곳에 있는 빈티지샵을 모아둔 지도입니다. 오래된 옷부터 희소성 있는 아카이브 제품까지, 개성 있는 빈티지샵을 함께 찾아보고 공유해 보세요.' where slug = 'korea-vintage';
update public.theme_maps set description = '도쿄 곳곳에 있는 패션 매장들을 모아둔 지도입니다. 잘 알려진 유명 매장부터 숨겨진 로컬 숍까지, 도쿄에서 쇼핑할 만한 곳들을 함께 찾아보고 공유해 보세요.' where slug = 'tokyo-fashion';
update public.theme_maps set description = '서울 곳곳에 있는 타코 맛집을 모아둔 지도입니다. 정통 멕시칸 타코부터 색다른 스타일의 타코까지, 맛있는 타코를 즐길 수 있는 곳들을 함께 찾아보고 공유해 보세요.' where slug = 'seoul-taco-restaurant';
update public.theme_maps set description = '최자로드에 소개된 전국의 맛집을 모아둔 지도입니다. 최자가 직접 방문하고 추천한 식당들을 한눈에 확인해보세요.' where slug = 'choiza-road-restaurants';
update public.theme_maps set description = '전국 곳곳의 맛있는 버거집을 모아가는 지도입니다. 직접 먹어보고 만족했던 버거집이 있다면 추천해 주세요. 여러 사람의 추천을 모아 국내 최고의 버거 맛집들을 찾아보세요.' where slug = 'korea-best-burger';
update public.theme_maps set description = '전국 곳곳의 사우나와 찜질방을 모아가는 지도입니다. 시설이 좋거나 특별한 매력이 있는 곳부터 동네의 숨은 명소까지, 직접 방문해 보고 만족했던 곳이 있다면 함께 추천해 주세요.' where slug = 'korea-sauna-map';
update public.theme_maps set description = '서울의 아름다운 야경을 감상할 수 있는 장소들을 모아가는 지도입니다. 탁 트인 전망을 즐길 수 있는 곳부터 조용히 야경을 감상하기 좋은 숨은 명소까지, 나만 알고 있기 아까운 장소가 있다면 함께 추천해 주세요.' where slug = 'seoul-night-view';
